'use client';

import { cn } from '@openpkg-ts/ui/lib/utils';
import { type ReactNode, useEffect, useRef } from 'react';
import { useSyncScroll } from '@/registry/new-york/hooks/use-sync-scroll/use-sync-scroll';

export interface MethodSectionProps {
  /** Section ID for scroll sync */
  id: string;
  /** Method title (e.g., "Fetch data") */
  title: string;
  /** Method signature (e.g., "select(columns?, options?)") */
  signature?: string;
  /** Method description */
  description?: ReactNode;
  /** Bullet list notes */
  notes?: string[];
  /** Parameter content */
  children?: ReactNode;
  /** Custom className */
  className?: string;
}

/**
 * Container for a single API method in the documentation.
 * Renders title, signature, description, notes list, and parameters.
 */
export function MethodSection({
  id,
  title,
  signature,
  description,
  notes,
  children,
  className,
}: MethodSectionProps): ReactNode {
  const ref = useRef<HTMLElement>(null);
  const syncScroll = useSyncScrollSafe();

  useEffect(() => {
    if (syncScroll && ref.current) {
      syncScroll.registerSection(id, ref);
      return () => syncScroll.unregisterSection(id);
    }
  }, [id, syncScroll]);

  return (
    <section
      ref={ref}
      id={id}
      data-section={id}
      className={cn('openpkg-method-section', 'mb-20 last:mb-0', className)}
    >
      <h2
        className={cn(
          'text-2xl font-semibold tracking-tight',
          'text-[var(--openpkg-text-primary)]',
          'mb-4',
        )}
      >
        {title}
      </h2>

      {signature && (
        <code className={cn('block font-mono text-sm', 'text-[var(--openpkg-text-muted)]', 'mb-6')}>
          {signature}
        </code>
      )}

      {description && (
        <div
          className={cn(
            'openpkg-method-description',
            'text-[15px] leading-relaxed',
            'text-[var(--openpkg-text-secondary)]',
            'mb-6',
            '[&_a]:text-[var(--openpkg-accent-link)] [&_a]:no-underline [&_a]:font-medium hover:[&_a]:underline',
            '[&_code]:bg-[var(--openpkg-bg-badge)] [&_code]:px-1.5 [&_code]:py-0.5 [&_code]:rounded [&_code]:font-mono [&_code]:text-[13px]',
          )}
        >
          {typeof description === 'string' ? <p>{description}</p> : description}
        </div>
      )}

      {notes && notes.length > 0 && (
        <ul
          className={cn(
            'openpkg-method-notes',
            'list-disc list-inside',
            'text-[15px] leading-relaxed',
            'text-[var(--openpkg-text-secondary)]',
            'mb-8 space-y-2',
          )}
        >
          {notes.map((note, i) => (
            <li key={i}>{note}</li>
          ))}
        </ul>
      )}

      {children && (
        <div className="openpkg-method-params">
          <h3
            className={cn(
              'text-xs font-semibold uppercase tracking-wider',
              'text-[var(--openpkg-text-muted)]',
              'mb-4 pb-2',
              'border-b border-[var(--openpkg-border-subtle)]',
            )}
          >
            Parameters
          </h3>
          {children}
        </div>
      )}
    </section>
  );
}

function useSyncScrollSafe() {
  try {
    return useSyncScroll();
  } catch {
    return null;
  }
}
